def solve(line: str):
    """Parse a single CSV line according to simplified RFC 4180 rules.
    - Fields are separated by commas.
    - A field may be quoted with double quotes. Quoted fields may contain commas
      and escaped double quotes ("" -> ").
    - Quoting is only recognized if the first character of the field is a quote.
    - Empty line yields a list with a single empty string.
    """
    if line == "":
        return [""]
    fields = []
    field_chars = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Escaped double quote?
                if i + 1 < n and line[i + 1] == '"':
                    field_chars.append('"')
                    i += 1  # skip the escaped quote
                else:
                    in_quotes = False
            else:
