def solve(coins, amount):
    """Return the fewest coins summing to amount, or -1 if impossible.

    Bottom-up DP over amounts; each coin may be used unlimited times.
    """
    INF = amount + 1
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if 0 <= c <= a and dp[a - c] + 1 < best:
                best = dp[a - c] + 1
        dp[a] = best
    return dp[amount] if dp[amount] <= amount else -1

