    """Simplify an absolute Unix path.
    Handles '.', '..', redundant slashes and removes trailing slash.
    """
    if not isinstance(path, str) or not path.startswith('/'):
        # According to the problem the input should be a valid absolute path.
        # Return empty string for invalid input.
        return ''
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

