def solve(s):
    """Convert a Roman numeral to an integer.
    The input is expected to be a valid Roman numeral consisting of the characters
    I, V, X, L, C, D, M (case‑insensitive) possibly surrounded by whitespace.
    If the input contains any other characters, the function returns 0.
    """
    if not isinstance(s, str):
        return 0
    s = s.strip().upper()
    if s == '':
        return 0
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
              'C': 100, 'D': 500, 'M': 1000}
    # Validate characters
    for ch in s:
        if ch not in values:
            return 0
    total = 0
    prev = 0
    for ch in reversed(s):
        val = values[ch]
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total

