def solve(s):
    n = len(s)
    if n == 0:
        return ''
    best = (0, 1)  # start, length
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - l - 1  # start, length
    for i in range(n):
        # odd length
        start, length = expand(i, i)
        if length > best[1]:
            best = (start, length)
        # even length
        start, length = expand(i, i+1)
        if length > best[1]:
            best = (start, length)
    return s[best[0]:best[0]+best[1]]

