def solve(grid):
    """Return the number of islands in a binary grid.
    Cells are connected orthogonally (up, down, left, right).
    The grid may be non‑rectangular (rows can have different lengths).
    Empty grid returns 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def neighbors(r, c):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i, j))
            for ni, nj in neighbors(i, j):
                if (ni, nj) not in visited and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

