    """Validate an IPv4 address.
    Accepts a string or bytes-like object. Returns True iff the address consists of
    exactly four decimal numbers (0-255) separated by dots, with no leading zeros
    unless the number is exactly '0'. Surrounding whitespace is ignored.
    """
    # Accept bytes, bytearray, memoryview and decode to str
    if isinstance(s, (bytes, bytearray, memoryview)):
        try:
            s = s.decode('utf-8')
        except Exception:
            return False
    if not isinstance(s, str):
        return False
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        # Reject leading zeros (e.g., '01') unless the part is exactly '0'
        if len(part) > 1 and part[0] == '0':
