def solve(path):
    """Simplify an absolute Unix path.
    Handles non‑string input by returning '/'.
    Collapses '.' and '..' components and redundant slashes.
    """
    if not isinstance(path, str):
        return '/'
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

